      Alert_alert_04,
      "\"use client\";\r\n\r\nimport { useState } from \"react\";\r\nimport { AlertTriangle, X, Trash2 } from \"lucide-react\";\r\nimport { cn } from \"@/lib/utils\";\r\n\r\ninterface Alert04Props {\r\n  title?: string;\r\n  message?: string;\r\n  confirmLabel?: string;\r\n  cancelLabel?: string;\r\n  onConfirm?: () => void;\r\n  onCancel?: () => void;\r\n  className?: string;\r\n}\r\n\r\nexport default function Alert04({\r\n  title = \"Delete project?\",\r\n  message = \"This action cannot be undone. All data associated with this project will be permanently removed.\",\r\n  confirmLabel = \"Delete\",\r\n  cancelLabel = \"Cancel\",\r\n  onConfirm,\r\n  onCancel,\r\n  className,\r\n}: Alert04Props) {\r\n  const [isVisible, setIsVisible] = useState(true);\r\n  const [isExiting, setIsExiting] = useState(false);\r\n  const [isDeleting, setIsDeleting] = useState(false);\r\n\r\n  const handleCancel = () => {\r\n    setIsExiting(true);\r\n    setTimeout(() => {\r\n      setIsVisible(false);\r\n      onCancel?.();\r\n    }, 200);\r\n  };\r\n\r\n  const handleConfirm = () => {\r\n    setIsDeleting(true);\r\n    setTimeout(() => {\r\n      onConfirm?.();\r\n      handleCancel();\r\n    }, 800);\r\n  };\r\n\r\n  if (!isVisible) return null;\r\n\r\n  return (\r\n    <div className={cn(\"w-full max-w-md mx-auto\", className)}>\r\n      <div\r\n        className={cn(\r\n          \"relative rounded-xl overflow-hidden\",\r\n          \"bg-white dark:bg-zinc-900\",\r\n          \"border border-red-200 dark:border-red-900/50\",\r\n          \"shadow-[0_4px_16px_0_rgba(239,68,68,0.1)] dark:shadow-[0_4px_16px_0_rgba(239,68,68,0.05)]\",\r\n          \"transition-all duration-200\",\r\n          isExiting && \"opacity-0 scale-95\",\r\n        )}\r\n        role=\"alertdialog\"\r\n        aria-labelledby=\"alert-title\"\r\n        aria-describedby=\"alert-description\"\r\n      >\r\n        <div className=\"p-5\">\r\n          <div className=\"flex gap-4\">\r\n            <div className=\"flex-shrink-0\">\r\n              <div className=\"p-2.5 rounded-full bg-red-100 dark:bg-red-950/50\">\r\n                <AlertTriangle className=\"h-5 w-5 text-red-600 dark:text-red-400\" />\r\n              </div>\r\n            </div>\r\n\r\n            <div className=\"flex-1\">\r\n              <h3\r\n                id=\"alert-title\"\r\n                className=\"text-base font-semibold text-zinc-900 dark:text-zinc-100\"\r\n              >\r\n                {title}\r\n              </h3>\r\n              <p\r\n                id=\"alert-description\"\r\n                className=\"mt-2 text-sm text-zinc-600 dark:text-zinc-400 leading-relaxed\"\r\n              >\r\n                {message}\r\n              </p>\r\n            </div>\r\n\r\n            <button\r\n              onClick={handleCancel}\r\n              className={cn(\r\n                \"flex-shrink-0 self-start p-1 rounded-md -mt-1 -mr-1\",\r\n                \"text-zinc-400 hover:text-zinc-600 dark:text-zinc-500 dark:hover:text-zinc-300\",\r\n                \"hover:bg-zinc-100 dark:hover:bg-zinc-800\",\r\n                \"transition-colors duration-150\",\r\n                \"focus:outline-none focus:ring-2 focus:ring-zinc-400\",\r\n              )}\r\n              aria-label=\"Close\"\r\n            >\r\n              <X className=\"h-4 w-4\" />\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <div className=\"px-5 py-4 bg-zinc-50 dark:bg-zinc-800/50 border-t border-zinc-200 dark:border-zinc-800\">\r\n          <div className=\"flex justify-end gap-3\">\r\n            <button\r\n              onClick={handleCancel}\r\n              className={cn(\r\n                \"px-4 py-2 text-sm font-medium rounded-lg\",\r\n                \"text-zinc-700 dark:text-zinc-300\",\r\n                \"bg-white dark:bg-zinc-800\",\r\n                \"border border-zinc-300 dark:border-zinc-700\",\r\n                \"hover:bg-zinc-50 dark:hover:bg-zinc-700\",\r\n                \"transition-colors duration-150\",\r\n                \"focus:outline-none focus:ring-2 focus:ring-zinc-400 focus:ring-offset-2\",\r\n                \"dark:focus:ring-offset-zinc-900\",\r\n              )}\r\n            >\r\n              {cancelLabel}\r\n            </button>\r\n            <button\r\n              onClick={handleConfirm}\r\n              disabled={isDeleting}\r\n              className={cn(\r\n                \"inline-flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg\",\r\n                \"bg-red-600 hover:bg-red-700 text-white\",\r\n                \"transition-all duration-150\",\r\n                \"disabled:opacity-70 disabled:cursor-not-allowed\",\r\n                \"focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2\",\r\n                \"dark:focus:ring-offset-zinc-900\",\r\n              )}\r\n            >\r\n              {isDeleting ? (\r\n                <>\r\n                  <div className=\"h-4 w-4 border-2 border-white/30 border-t-white rounded-full animate-spin\" />\r\n                  Deleting...\r\n                </>\r\n              ) : (\r\n                <>\r\n                  <Trash2 className=\"h-4 w-4\" />\r\n                  {confirmLabel}\r\n                </>\r\n              )}\r\n            </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n",
      { previewClassName: "min-h-[120px] w-full max-w-lg" }
